-- name: seed_curated_course_video_courses
-- =============================================================================
-- Seed curated_courses from degrees-page curated curricula
-- (undergraduate + graduate JSON). One row per unique course name slug.
-- Does NOT insert syllabus nodes/videos — placeholders only.
-- Safe to re-run: upserts on slug. Leaves existing fluid-mechanics tree intact.
-- =============================================================================

on conflict (slug) do update set
  title = excluded.title,
  description = coalesce(excluded.description, public.curated_courses.description),
  updated_at = now();

-- 1845 unique curated courses (from UG + graduate degrees pages)
